def partial_consistent?(partial)
  partial.each { |parameter_index, value_index|
    partial.each { |other_parameter, other_value|
      if parameter_index == other_parameter
        next
      end
      if invalid_pairs_for([value_index]).include?([other_parameter, other_value])
        return false
      end
    }
  }
  @higher_order.each { |antecedents, forbidden|
    if antecedents.all? { |parameter_index, value_index|
      partial[parameter_index] == value_index
    }
      if partial[forbidden[0]] == forbidden[1]
        return false
      end
    end
  }
  true
end

